/* 6280 ********************************************************
 *  LSR Logic shift right
 *  0 -> [7][6][5][4][3][2][1][0] -> C
 ***************************************************************/
static inline uint8_t lsr(uint8_t tmp)
{
	clear_t();
	P = (P & ~_fC) | (tmp & _fC);
	tmp = (uint8_t)tmp >> 1;
	set_nz(tmp);
	return tmp;
}

