/* H6280 *******************************************************
 *  TAI Transfer Alternate Increment
 ***************************************************************/
static __attribute__((noinline)) void tai()
{
	clear_t();
	int from = program_read16(PCW);
	int to = program_read16(PCW + 2);
	int length = program_read16(PCW + 4);
	PCW += 6;
	int alternate = 0;
	if (!length) length = 0x10000;
	h6280_cycles( ((6 * length) + 17) );
	while ((length--) != 0)
	{
		program_write8(to, program_read8(from + alternate));
		to++;
		alternate ^= 1;
	}
}

/* H6280 *******************************************************
 *  TAM Transfer accumulator to memory mapper register(s)
 ***************************************************************/
static inline void tam(uint8_t tmp)
{
	clear_t();
	if (tmp&0x01) { m_mmr[0] = A; pce_mpr_changed(0); }
	if (tmp&0x02) { m_mmr[1] = A; pce_mpr_changed(1); }
	if (tmp&0x04) { m_mmr[2] = A; pce_mpr_changed(2); }
	if (tmp&0x08) { m_mmr[3] = A; pce_mpr_changed(3); }
	if (tmp&0x10) { m_mmr[4] = A; pce_mpr_changed(4); }
	if (tmp&0x20) { m_mmr[5] = A; pce_mpr_changed(5); }
	if (tmp&0x40) { m_mmr[6] = A; pce_mpr_changed(6); }
	if (tmp&0x80) { m_mmr[7] = A; pce_mpr_changed(7); }
}

